using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.RateLimiting;using System.Threading.RateLimiting;
var b=WebApplication.CreateBuilder(args);b.Services.AddReverseProxy().LoadFromConfig(b.Configuration.GetSection("ReverseProxy"));b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.Authority=b.Configuration["Authentication:Authority"];o.Audience="health-api";o.RequireHttpsMetadata=!b.Environment.IsDevelopment();});b.Services.AddAuthorization();b.Services.AddRateLimiter(o=>{o.RejectionStatusCode=429;o.AddFixedWindowLimiter("edge",x=>{x.PermitLimit=1000;x.Window=TimeSpan.FromMinutes(1);});});var app=b.Build();app.Use(async(ctx,next)=>{ctx.Request.Headers["X-Correlation-Id"]=Guid.NewGuid().ToString("N");await next();});app.UseAuthentication();app.UseAuthorization();app.UseRateLimiter();app.MapReverseProxy().RequireAuthorization().RequireRateLimiting("edge");app.Run();
